export async function healSearchReplace(file: string, oldText: string, newText: string) {
  const actual = await fs.readFile(file, 'utf8');
  if (!actual.includes(oldText)) return { healed: false, reason: 'context mismatch' };
  return { healed: true };
}

export async function healApplyPatch(file: string, hunks: Hunk[]) {
  return applyWithContextFuzz(file, hunks);
}

